// Ce fichier ne doit PAS etre modifie a la main : les codes sont
// stockes sous une forme encodee pour ne pas etre lisibles a l'oeil
// nu par un visiteur qui ouvrirait le code source de la page.
//
// Pour AJOUTER ou RETIRER des codes, utilisez le fichier
// "generateur-codes.html" fourni a part : il vous permet de gerer
// la liste en clair et de regenerer automatiquement ce fichier.
// Ne partagez jamais generateur-codes.html avec vos clients.
// ============================================================
(function(){
  var _k = "CHICKNSTER2026";
  var _e = "";
  function _decode(b64, key){
    var bin = atob(b64);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    var out = new Uint8Array(bytes.length);
    for (var j = 0; j < bytes.length; j++) out[j] = bytes[j] ^ key.charCodeAt(j % key.length);
    var str = '';
    for (var k = 0; k < out.length; k++) str += String.fromCharCode(out[k]);
    return decodeURIComponent(escape(str));
  }
  window.VALID_CODES = JSON.parse(_decode(_e, _k));
})();
